let activeLanguage: Language = "es";
export const LANGUAGE_CHANGE_EVENT = "jw-tracker-language-change";

export function getLanguage(): Language {
  return activeLanguage;
}

export function setLanguage(language: Language): void {
  if (activeLanguage === language) return;
  activeLanguage = language;
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(LANGUAGE_CHANGE_EVENT, { detail: { lang: language } }));
  }
}

export function subscribeLanguageChange(listener: (language: Language) => void): () => void {
  if (typeof window === "undefined") return () => undefined;
  const handler = (event: Event) => listener((event as CustomEvent<{ lang: Language }>).detail.lang);
  window.addEventListener(LANGUAGE_CHANGE_EVENT, handler);
  return () => window.removeEventListener(LANGUAGE_CHANGE_EVENT, handler);
}

export function translate(message: string, language: Language = activeLanguage): string {
  return language === "es" ? message : messages[language][message] ?? message;
}

export function getLocale(language: Language = activeLanguage): string {
  return locales[language];
}

export function toStoredLabel(label: string, choices?: string[]): string {
  if (choices) return choices.find((choice) => translate(choice) === label) ?? label;
  if (activeLanguage === "es") return label;
  return Object.entries(messages[activeLanguage]).find(([, translated]) => translated === label)?.[0] ?? label;
}
